package tri_lion.health.repository.routine;import java.time.LocalDate;import java.util.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.JpaRepository;import tri_lion.health.domain.routine.*;
public final class RoutineRepositories{private RoutineRepositories(){}public interface Routines extends JpaRepository<Routine,Long>{Optional<Routine>findByIdAndUserIdAndDeletedAtIsNull(Long id,Long user);Page<Routine>findByUserIdAndDeletedAtIsNullOrderByUpdatedAtDesc(Long user,Pageable p);Optional<Routine>findFirstByUserIdAndStartDateLessThanEqualAndEndDateGreaterThanEqualAndDeletedAtIsNullOrderByCreatedAtDesc(Long user,LocalDate a,LocalDate b);}public interface Days extends JpaRepository<RoutineDay,Long>{List<RoutineDay>findByRoutineIdOrderByScheduledDate(Long id);Optional<RoutineDay>findByIdAndRoutineId(Long id,Long r);Optional<RoutineDay>findByRoutineIdAndScheduledDate(Long r,LocalDate date);}public interface Sections extends JpaRepository<RoutineSection,Long>{List<RoutineSection>findByRoutineDayIdOrderBySortOrder(Long day);Optional<RoutineSection>findByIdAndRoutineDayIdIn(Long id,Collection<Long>days);}public interface Items extends JpaRepository<ExerciseItem,Long>{List<ExerciseItem>findByRoutineIdAndDeletedAtIsNullOrderBySortOrder(Long r);List<ExerciseItem>findBySectionIdAndDeletedAtIsNullOrderBySortOrder(Long s);Optional<ExerciseItem>findByIdAndRoutineIdAndDeletedAtIsNull(Long id,Long routine);}}
